{
  "task": "scope_01",
  "records": [
    {
      "id": "C06",
      "title": "Joint Model Partitioning and Bandwidth Allocation for UAV-Assisted Space–Air–Ground–Sea Integrated Network: A Hybrid A3C-PPO Approach",
      "authors": [
        "Yuanmo Lin",
        "Yuanyuan Han",
        "Minmin Wu",
        "Shaoyu Lin",
        "Xia Zhang",
        "Zhiyong Xu"
      ],
      "year": 2026,
      "venue": "Entropy",
      "doi": "10.3390/e28030337",
      "prior_decision": "UNCERTAIN",
      "other_gates_preserved": {
        "primary_full_report": "YES",
        "evaluative_evidence": "YES",
        "date_window": "YES",
        "english": "YES"
      },
      "proposed_decision": "UNCERTAIN",
      "scope_gates": {
        "multi_uav_evaluated": {
          "status": "UNCERTAIN",
          "rationale": "Simulation settings specify three UAVs hovering at 40–100 m (C06_E3) and one central UAV plus worker UAVs for policy sampling (C06_E2), whereas the experimental configuration statement identically pairs four intelligent terminals with the singular UAV (C06_E4).",
          "evidence_ids": [
            "C06_E2",
            "C06_E3",
            "C06_E4"
          ]
        },
        "collaborative_inference": {
          "status": "UNCERTAIN",
          "rationale": "DNN inference is partitioned between each intelligent terminal and a UAV edge server (C06_E1), while central-to-worker UAV roles in C06_E2 coordinate global policy hosting, state collection, and policy sampling rather than clearly separating inference-time orchestration across the three UAVs from per-UAV runs (C06_E2, C06_E3, C06_E4).",
          "evidence_ids": [
            "C06_E1",
            "C06_E2",
            "C06_E3",
            "C06_E4"
          ]
        }
      },
      "architecture": {
        "uav_roles": "Three UAVs are configured in SAGSIN simulation settings (C06_E3), with one UAV described as hosting a global policy network and other UAVs acting as worker agents for local state collection and policy sampling (C06_E2), while experimental text also describes four terminals connected to the UAV (C06_E4).",
        "inference_execution_nodes": "Intelligent terminals execute the front DNN partition and a UAV edge server executes the remaining DNN partition from transmitted intermediate feature results (C06_E1).",
        "inference_workload": "Partitioned DNN inference tasks continuously generated by connected intelligent terminals (C06_E1, C06_E4).",
        "coordinated_decisions": "Two-part DNN model partitioning per terminal-UAV pair (C06_E1) combined with global policy decision-making on a central node and local state collection/policy sampling by worker agents under A3C-PPO (C06_E2, C06_E4).",
        "evaluated_conditions": "Simulated UAV-assisted SAGSIN edge scenarios with three hovering UAVs at 40–100 m (C06_E3) alongside experiments configured identically to A3C-PPO with four terminals connected to the UAV (C06_E4).",
        "evidence_ids": [
          "C06_E1",
          "C06_E2",
          "C06_E3",
          "C06_E4"
        ]
      },
      "supporting_interpretation": {
        "note": "Under Amendment 001, simulation evidence is eligible if three deployed UAVs (C06_E3) host a central global policy UAV coordinating bandwidth and partition decisions across worker UAVs (C06_E2) for terminal-UAV split DNN inference (C06_E1), without requiring inter-UAV DNN layer splits.",
        "evidence_ids": [
          "C06_E1",
          "C06_E2",
          "C06_E3"
        ]
      },
      "contrary_interpretation": {
        "note": "Worker UAV activity in C06_E2 centers on local state collection and policy sampling (RL policy training/coordination), DNN splitting occurs strictly between one terminal and a UAV (C06_E1), and the experimental text in C06_E4 describes four terminals connected to the singular UAV, leaving multi-UAV evaluated inference ambiguous.",
        "evidence_ids": [
          "C06_E1",
          "C06_E2",
          "C06_E4"
        ]
      },
      "evidence": [
        {
          "evidence_id": "C06_E1",
          "file": "screening_46/text/C06.txt",
          "page": 6,
          "line_range": "282-285",
          "quote": "The DNN model is partitioned into two parts: the front part is executed locally on the intelligent terminal, and the intermediate feature results are transmitted to the UAV, where the remaining part is executed by the UAV of edge server."
        },
        {
          "evidence_id": "C06_E2",
          "file": "screening_46/text/C06.txt",
          "page": 13,
          "line_range": "716-719",
          "quote": "During deployment, one UAV serves as the central node hosting the global policy network for coordinated decision-making, while the remaining UAVs act as worker agents responsible for local state collection and policy sampling."
        },
        {
          "evidence_id": "C06_E3",
          "file": "screening_46/text/C06.txt",
          "page": 15,
          "line_range": "835-836",
          "quote": "Three UAVs are deployed in the UAV-assisted edge network under SAGSIN scenarios. UAVs hover at heights of 40–100 m above ground to execute predefined tasks."
        },
        {
          "evidence_id": "C06_E4",
          "file": "screening_46/text/C06.txt",
          "page": 20,
          "line_range": "1039-1041",
          "quote": "The experimental environment is configured identically to that of the A3C-PPO framework. Four intelligent terminals are connected to the UAV. Inference tasks are continuously generated by each terminal."
        }
      ],
      "unresolved": [
        "Clarify whether A3C-PPO performance curves evaluate joint runtime inference coordination across all three simulated UAVs (C06_E2, C06_E3) or aggregate per-UAV single-server experiments as phrased in C06_E4.",
        "Clarify whether worker-agent roles in C06_E2 operate only for RL policy training/sampling or coordinate live multi-UAV inference resource/partition assignments."
      ],
      "human_question": "Do the evaluated A3C-PPO inference results run across the three-UAV hierarchy (C06_E2, C06_E3) with runtime multi-UAV coordination, or are inference workloads evaluated per individual UAV with worker agents used only for RL policy training/sampling (C06_E4)?"
    },
    {
      "id": "SNCS",
      "title": "Learning-Based UAV Swarm Video Analytics Orchestration in Disaster Response Management",
      "authors": [
        "Tiying Gao",
        "Dwight Goins",
        "Chaise Ballotti",
        "Jiaqing Liu",
        "Chengyi Qu"
      ],
      "year": 2025,
      "venue": "SN Computer Science",
      "doi": "10.1007/s42979-025-04063-5",
      "prior_decision": "UNCERTAIN",
      "other_gates_preserved": {
        "primary_full_report": "YES",
        "evaluative_evidence": "YES",
        "date_window": "YES",
        "english": "YES"
      },
      "proposed_decision": "UNCERTAIN",
      "scope_gates": {
        "multi_uav_evaluated": {
          "status": "YES",
          "rationale": "The study explicitly evaluates a simulated multi-UAV network of 10 UAVs over 25 steps of RL algorithm runs for online networking collaboration (SNCS_E4).",
          "evidence_ids": [
            "SNCS_E4"
          ]
        },
        "collaborative_inference": {
          "status": "UNCERTAIN",
          "rationale": "YoloV8 object detection is run on 320 video clips on a Nvidia Jetson Xavier NX (SNCS_E1) with DQN/policy-based UAV-Edge-Server collaboration decisions evaluated over those clips (SNCS_E2), whereas the evaluated 10-UAV RL collaboration simulation (SNCS_E4) adjusts UAV movement and data receiving, forwarding, or dropping status (SNCS_E3), leaving runtime multi-UAV collaborative inference integration unresolved.",
          "evidence_ids": [
            "SNCS_E1",
            "SNCS_E2",
            "SNCS_E3",
            "SNCS_E4"
          ]
        }
      },
      "architecture": {
        "uav_roles": "Ten simulated UAVs in the online RL networking collaboration environment (SNCS_E4) executing position and data-handling actions (SNCS_E3), alongside a UAV-Edge-Server collaboration formulation for video analytics (SNCS_E2).",
        "inference_execution_nodes": "Real-time YoloV8 object detection executes on a Nvidia Jetson Xavier NX over 320 video clips (SNCS_E1) under evaluated UAV-Edge-Server collaboration policies (SNCS_E2).",
        "inference_workload": "YoloV8 real-time object detection across 320 video clips (SNCS_E1, SNCS_E2), separate from packet-forwarding and mobility decisions in the 10-UAV Q-learning routing simulation (SNCS_E3, SNCS_E4).",
        "coordinated_decisions": "DQN/policy-based UAV-Edge-Server collaboration decisions evaluated over 320 video clips (SNCS_E2) and multi-UAV RL actions controlling whether each UAV moves, stays, receives, forwards, or drops data (SNCS_E3, SNCS_E4).",
        "evaluated_conditions": "Hardware benchmark on Nvidia Jetson Xavier NX for YoloV8 detection across 320 video clips (SNCS_E1), policy/DQN vs. Oracle evaluation on the 320 clips (SNCS_E2), and 10-UAV 25-step RL networking simulation (SNCS_E4).",
        "evidence_ids": [
          "SNCS_E1",
          "SNCS_E2",
          "SNCS_E3",
          "SNCS_E4"
        ]
      },
      "supporting_interpretation": {
        "note": "Under Amendment 001, SNCS evaluates both multi-UAV RL networking orchestration across 10 UAVs (SNCS_E4) and policy/DQN-based UAV-Edge-Server video-analytics collaboration over 320 clips using YoloV8 (SNCS_E1, SNCS_E2); if the DQN/video-policy orchestration is judged coupled to the multi-UAV system, both scope gates would hold without physical flight.",
        "evidence_ids": [
          "SNCS_E1",
          "SNCS_E2",
          "SNCS_E4"
        ]
      },
      "contrary_interpretation": {
        "note": "The YoloV8 workload is measured on a single Nvidia Jetson Xavier NX over 320 video clips (SNCS_E1, SNCS_E2), while the 10-UAV RL simulation (SNCS_E4) coordinates movement and packet receiving, forwarding, or dropping status (SNCS_E3) rather than DNN inference execution, leaving collaborative multi-UAV inference unproven as one coupled runtime system (target journal SNCS cannot override scope).",
        "evidence_ids": [
          "SNCS_E1",
          "SNCS_E2",
          "SNCS_E3",
          "SNCS_E4"
        ]
      },
      "evidence": [
        {
          "evidence_id": "SNCS_E1",
          "file": "screening_46/text/SNCS.txt",
          "page": 17,
          "line_range": "1398-1402",
          "quote": "This effort resulted in the creation of 320 distinct video clips. These videos were then processed on a Nvidia Jetson Xavier NX using the YoloV8 model [48] to conduct real-time object detection, providing key confidence data and processing speed."
        },
        {
          "evidence_id": "SNCS_E2",
          "file": "screening_46/text/SNCS.txt",
          "page": 19,
          "line_range": "1552-1557",
          "quote": "Additionally, we conducted a subjective evaluation on all 320 video clips, manually assigning optimal collaboration decisions independent of the policy-based or DQN-based outputs. This Oracle approach represents the ideal UAV-Edge-Server collaboration solution."
        },
        {
          "evidence_id": "SNCS_E3",
          "file": "screening_46/text/SNCS.txt",
          "page": 14,
          "line_range": "1176-1178",
          "quote": "Here the action helps to determine if the UAV should move to another position or stay, change it’s status from receiving data, to forwarding data, to dropping data."
        },
        {
          "evidence_id": "SNCS_E4",
          "file": "screening_46/text/SNCS.txt",
          "page": 21,
          "line_range": "1724-1725",
          "quote": "Comparison of simulated multi-UAV (10 UAVs, 25 steps of RL algorithm runs) networking collaboration: initialization status (Left) vs. RL results (Right)"
        }
      ],
      "unresolved": [
        "Determine whether the 320-clip YoloV8 and DQN/policy-based UAV-Edge-Server collaboration experiments (SNCS_E1, SNCS_E2) are integrated into an evaluated multi-UAV inference hierarchy or remain decoupled from the 10-UAV Q-learning packet-routing simulation (SNCS_E3, SNCS_E4).",
        "Target journal venue (SN Computer Science) is non-evidential and excluded from eligibility adjudication."
      ],
      "human_question": "Does evaluating DQN-based UAV-Edge-Server video-analytics policy selection over 320 YoloV8 clips (SNCS_E1, SNCS_E2) alongside a separate 10-UAV Q-learning packet-forwarding/mobility simulation (SNCS_E3, SNCS_E4) satisfy multi-UAV collaborative inference under Amendment 001, or must both evaluations couple the same inference workload?"
    },
    {
      "id": "C04",
      "title": "A cognitive synergetic hierarchical framework for UAV swarm combat via speculative inference and role-decoupled reinforcement learning",
      "authors": [
        "Lixa Wang",
        "Yunqing Liu",
        "Linyang Guo",
        "Ran Zhang",
        "Yu Cui",
        "Yihan Cui",
        "Chunlin Xu"
      ],
      "year": 2026,
      "venue": "Frontiers in Neurorobotics",
      "doi": "10.3389/fnbot.2026.1799054",
      "prior_decision": "INCLUDE",
      "other_gates_preserved": {
        "primary_full_report": "YES",
        "evaluative_evidence": "YES",
        "date_window": "YES",
        "english": "YES"
      },
      "proposed_decision": "INCLUDE",
      "scope_gates": {
        "multi_uav_evaluated": {
          "status": "YES",
          "rationale": "The framework is explicitly evaluated in multi-UAV swarm combat scenarios including Scenario B (2v2 coordination) and Scenario C (6v6 scale combat) against five baselines (C04_E3).",
          "evidence_ids": [
            "C04_E3"
          ]
        },
        "collaborative_inference": {
          "status": "YES",
          "rationale": "Inference is jointly orchestrated both vertically via a cloud-to-edge speculative decoding pipeline combining 70B-level and 7B-level models (C04_E1) and horizontally via intra-swarm broadcast and fusion of intention embeddings into a cumulative Shared Mental Model for peer action inference (C04_E2).",
          "evidence_ids": [
            "C04_E1",
            "C04_E2",
            "C04_E4"
          ]
        }
      },
      "architecture": {
        "uav_roles": "Multi-UAV swarm agents organized with a Leader broadcasting its intention embedding to subsequent peer UAVs in 2v2 and 6v6 combat teams (C04_E2, C04_E3).",
        "inference_execution_nodes": "Cloud-to-edge 70B/7B speculative decoding pipeline plus onboard/peer swarm policy inference sharing intention embeddings via Sequential Intention Propagation (C04_E1, C04_E2, C04_E4).",
        "inference_workload": "70B/7B speculative LLM strategic reasoning paired with runtime multi-agent intention embedding generation and policy inference within a 50 Hz control window (C04_E1, C04_E2, C04_E4).",
        "coordinated_decisions": "Speculative draft-and-verify inference across 70B and 7B tiers (C04_E1) and cascaded swarm-wide intention embedding broadcast/aggregation into a Shared Mental Model conditioning downstream UAV policies (C04_E2, C04_E4).",
        "evaluated_conditions": "Simulated multi-UAV combat evaluations in Scenario B (2v2) and Scenario C (6v6) against five baselines (C04_E3), where Sequential Intention Propagation resolves within 20 ms in simulation (C04_E4).",
        "evidence_ids": [
          "C04_E1",
          "C04_E2",
          "C04_E3",
          "C04_E4"
        ]
      },
      "supporting_interpretation": {
        "note": "Under Amendment 001, simulation evidence is eligible and C04 satisfies both gates through evaluated 2v2 and 6v6 swarms (C04_E3) combining vertical 70B/7B cloud-to-edge speculative inference (C04_E1) with runtime intra-swarm latent intention embedding fusion via Sequential Intention Propagation (C04_E2, C04_E4).",
        "evidence_ids": [
          "C04_E1",
          "C04_E2",
          "C04_E3",
          "C04_E4"
        ]
      },
      "contrary_interpretation": {
        "note": "Limiting considerations are that multi-UAV swarm combat experiments and the 20 ms Sequential Intention Propagation timing are established in simulation rather than multi-UAV physical flight, and the authors note physical large-swarm cascaded transmission would exceed the 50 Hz control window (C04_E3, C04_E4); however, physical flight is not required under Amendment 001.",
        "evidence_ids": [
          "C04_E3",
          "C04_E4"
        ]
      },
      "evidence": [
        {
          "evidence_id": "C04_E1",
          "file": "screening_46/text/C04.txt",
          "page": 8,
          "line_range": "670-672",
          "quote": "To get 70B-level intelligence at 7B-level speeds on the edge, we’ve built a “cloud-to-edge” inference pipeline based on speculative decoding."
        },
        {
          "evidence_id": "C04_E2",
          "file": "screening_46/text/C04.txt",
          "page": 9,
          "line_range": "799-803",
          "quote": "The Leader (u(1)) outputs its intention embedding m(1),t, which is broadcasted to all subsequent peers. Each following agent then updates the “Shared Mental Model” by adding its own intended vector to the pool."
        },
        {
          "evidence_id": "C04_E3",
          "file": "screening_46/text/C04.txt",
          "page": 13,
          "line_range": "1173-1176",
          "quote": "To see if our architecture actually gives a tactical edge, we ran our Brain-Torso setup against five baselines in Scenario B (2v2 coordination) and Scenario C (6v6 scale combat; scenario specifics are outlined in Section 5.1.2)."
        },
        {
          "evidence_id": "C04_E4",
          "file": "screening_46/text/C04.txt",
          "page": 20,
          "line_range": "1736-1741",
          "quote": "while our Sequential Intention Propagation (SIP) mechanism resolves within 20 ms in simulation, real-world cascaded transmission across a large swarm will inevitably accumulate multi-hop latency that exceeds this 50 Hz control window, potentially degrading aerodynamic stability."
        }
      ],
      "unresolved": [
        "No scope-gate ambiguity remains under Amendment 001; retain note that swarm-scale Sequential Intention Propagation timing (20 ms vs. 50 Hz control window) is simulation-based and flagged for physical latency scaling in Section 6 (C04_E4), pending final human adjudication."
      ],
      "human_question": null
    },
    {
      "id": "C11",
      "title": "Quantum-Enhanced Multi-Agent Reinforcement Learning for Ubiquitous LLM Inference via Embodied UAV Swarms",
      "authors": [
        "Xiangdong Zheng",
        "Long Luo",
        "Hongfang Yu",
        "Haoxiang Luo"
      ],
      "year": 2026,
      "venue": "IEEE Transactions on Cognitive Communications and Networking",
      "doi": "10.1109/TCCN.2026.3716252",
      "prior_decision": "INCLUDE",
      "other_gates_preserved": {
        "primary_full_report": "YES",
        "evaluative_evidence": "YES",
        "date_window": "YES",
        "english": "YES"
      },
      "proposed_decision": "INCLUDE",
      "scope_gates": {
        "multi_uav_evaluated": {
          "status": "YES",
          "rationale": "Both evaluated simulation scenarios deploy two rotary-wing UAVs (U = 2) from [0, 500] and [500, 500] m at H = 100 m (C11_E3).",
          "evidence_ids": [
            "C11_E3"
          ]
        },
        "collaborative_inference": {
          "status": "YES",
          "rationale": "Across the multi-UAV–edge-server hierarchy, the embodied UAV swarm actively senses user mobility and neighbor UAV states to coordinate local trajectory control, user association, and LLM inference-request routing (C11_E1) while terrestrial ESs execute prefill and token decoding streamed back via the UAV-assisted downlink (C11_E2); Amendment 001 does not require UAVs themselves to execute LLM layers.",
          "evidence_ids": [
            "C11_E1",
            "C11_E2",
            "C11_E3"
          ]
        }
      },
      "architecture": {
        "uav_roles": "Embodied two-UAV relay and orchestration swarm (U = 2) sensing user mobility and neighbor UAV states to execute trajectory, user-association, and inference-request routing decisions while relaying uplink/downlink LLM tokens (C11_E1, C11_E2, C11_E3).",
        "inference_execution_nodes": "Terrestrial edge servers (ESs) execute LLM prefill using uncached historical context and decode output tokens, while UAVs execute local sensing/routing policies and relay streams (C11_E1, C11_E2).",
        "inference_workload": "Multi-turn LLM prefill and token decoding on terrestrial ESs (C11_E2) paired with onboard multi-UAV policy decisions for cache-aware inference-request routing (C11_E1).",
        "coordinated_decisions": "Joint multi-UAV trajectory control, user association, and inference-request routing across UAVs and terrestrial ESs (C11_E1, C11_E2), trained via entangled learning updates (C11_E4).",
        "evaluated_conditions": "Simulated multi-UAV–ES edge inference scenarios with U = 2 rotary-wing UAVs at H = 100 m (C11_E3), treating quantum/platform imperfections as constraints outside the upper-layer routing model (C11_E4).",
        "evidence_ids": [
          "C11_E1",
          "C11_E2",
          "C11_E3",
          "C11_E4"
        ]
      },
      "supporting_interpretation": {
        "note": "Under Amendment 001, not every UAV (or UAV node vs. ES) must execute neural inference layers; C11 explicitly evaluates two UAVs (C11_E3) jointly orchestrating user association and LLM inference-request routing with terrestrial ES prefill/decoding across a multi-UAV–edge hierarchy (C11_E1, C11_E2).",
        "evidence_ids": [
          "C11_E1",
          "C11_E2",
          "C11_E3"
        ]
      },
      "contrary_interpretation": {
        "note": "Limiting considerations are that the UAVs serve strictly as wireless relays/routing agents while terrestrial ESs perform all LLM prefill and decoding (C11_E2), quantum entanglement is confined to learning updates, and hardware imperfections (blockage, photon loss, decoherence) sit outside the evaluated upper-layer routing model (C11_E4); nevertheless, inference-request routing across a two-UAV–ES hierarchy meets Amendment 001.",
        "evidence_ids": [
          "C11_E1",
          "C11_E2",
          "C11_E4"
        ]
      },
      "evidence": [
        {
          "evidence_id": "C11_E1",
          "file": "screening_46/text/C11.txt",
          "page": 1,
          "line_range": "16-20",
          "quote": "this paper studies an edge inference system assisted by an embodied UAV agent swarm, where UAVs actively sense user mobility and neighboring UAV states to make local decisions on trajectory control, user association, and inference-request routing."
        },
        {
          "evidence_id": "C11_E2",
          "file": "screening_46/text/C11.txt",
          "page": 4,
          "line_range": "373-376",
          "quote": "the ES performs prefill using the new input and the uncached historical context. Then, the ES decodes output tokens and streams the generated tokens back to the user through the UAV-assisted downlink."
        },
        {
          "evidence_id": "C11_E3",
          "file": "screening_46/text/C11.txt",
          "page": 8,
          "line_range": "911-913",
          "quote": "In both scenarios, two rotary-wing UAVs, i.e., U = 2, deploy from [0, 500] and [500, 500] m at a constant altitude H = 100 m."
        },
        {
          "evidence_id": "C11_E4",
          "file": "screening_46/text/C11.txt",
          "page": 7,
          "line_range": "764-768",
          "quote": "The entangled resources are consumed during learning updates rather than assumed to persist over the full mission horizon; platform-level imperfections such as blockage, photon loss, and decoherence are treated as implementation constraints outside the upper-layer routing model."
        }
      ],
      "unresolved": [
        "No scope-gate ambiguity under Amendment 001; note for final human review that UAVs execute routing/relaying rather than LLM prefill/decoding layers (C11_E1, C11_E2) and platform-level physical imperfections lie outside the upper-layer simulation model (C11_E4)."
      ],
      "human_question": null
    },
    {
      "id": "C16",
      "title": "Secure Split Offloading and Trajectory Design for UAV-Assisted Multi-Exit Collaborative DNN Inference",
      "authors": [
        "Mengru Wu",
        "Haonan Wu",
        "Weidang Lu",
        "Zhaolong Ning",
        "Lei Guo",
        "Abbas Jamalipour"
      ],
      "year": 2026,
      "venue": "IEEE Transactions on Mobile Computing",
      "doi": "10.1109/TMC.2026.3708394",
      "prior_decision": "INCLUDE",
      "other_gates_preserved": {
        "primary_full_report": "YES",
        "evaluative_evidence": "YES",
        "date_window": "YES",
        "english": "YES"
      },
      "proposed_decision": "INCLUDE",
      "scope_gates": {
        "multi_uav_evaluated": {
          "status": "YES",
          "rationale": "Simulations explicitly deploy and evaluate two UAVs—a UAV server and a cooperative UAV jammer—within an 800 × 800 m2 area (C16_E4).",
          "evidence_ids": [
            "C16_E4"
          ]
        },
        "collaborative_inference": {
          "status": "YES",
          "rationale": "Multi-exit DNN inference is split layer-wise between device k (layers 0 to mk[n]) and the UAV server (layers mk[n] + 1 to Msk[n]) (C16_E3) while jointly optimizing dual-UAV trajectories, early-exit selection, DNN partitioning, and compute allocation under secure offloading rate constraints supported by the UAV jammer's artificial noise (C16_E1, C16_E2); Amendment 001 does not require both UAVs to compute DNN layers.",
          "evidence_ids": [
            "C16_E1",
            "C16_E2",
            "C16_E3",
            "C16_E4"
          ]
        }
      },
      "architecture": {
