titles = []

for r in payload["records"]:
    cid = r["id"]
    acc = accepted_map[cid]
    assert r["title"] == acc["title"]
    assert r["authors"] == acc["authors"]
    assert r["year"] == acc["year"]
    assert r["venue"] == acc["venue"]
    assert r["doi"] == acc["doi"]
    assert r["prior_decision"] == acc["decision"]
    dois.append(r["doi"])
    titles.append(r["title"])
    assert len(r["evidence"]) == 4
    local_ids = set()
    for ev in r["evidence"]:
        assert ev["evidence_id"] not in all_ev_ids
        all_ev_ids.add(ev["evidence_id"])
        local_ids.add(ev["evidence_id"])
        wc = len(ev["quote"].split())
        assert 1 <= wc <= 40, f"{ev['evidence_id']} word count {wc}"
    six = [
        r["scope_gates"]["multi_uav_evaluated"]["status"],
        r["scope_gates"]["collaborative_inference"]["status"],
        r["other_gates_preserved"]["primary_full_report"],
        r["other_gates_preserved"]["evaluative_evidence"],
        r["other_gates_preserved"]["date_window"],
        r["other_gates_preserved"]["english"],
    ]
    if all(s == "YES" for s in six):
        expected = "INCLUDE"
    elif any(s == "NO" for s in six):
        expected = "EXCLUDE"
    else:
        expected = "UNCERTAIN"
    assert r["proposed_decision"] == expected
    if expected == "UNCERTAIN":
        assert isinstance(r["human_question"], str) and len(r["human_question"]) > 10
    else:
        assert r["human_question"] is None
    assert len(r["unresolved"]) >= 1
    for sec in [r["scope_gates"]["multi_uav_evaluated"], r["scope_gates"]["collaborative_inference"],
                r["architecture"], r["supporting_interpretation"], r["contrary_interpretation"]]:
        assert len(sec["evidence_ids"]) >= 1
        assert set(sec["evidence_ids"]).issubset(local_ids)

